// Renders public/roadmap.html (generated by `npm run plan` from plan/plan.json,
// plan 14.5) from its inline JSON block: [[phaseNumber, phaseTitle, [[id, state, title], …]], …].
// External (not inline) so the page works under script-src 'self', and it
// builds DOM nodes with textContent so it needs no Trusted Types policy.
(function () {
  const data = JSON.parse(document.getElementById("roadmap-data").textContent);
  const root = document.getElementById("phases");
  const label = { done: "הושלם", partial: "בעבודה", planned: "מתוכנן" };
  for (const [n, title, items] of data) {
    const h2 = document.createElement("h2");
    h2.className = "phase";
    const num = document.createElement("span");
    num.className = "n";
    num.textContent = String(n);
    h2.append(num, document.createTextNode(title));
    const grid = document.createElement("div");
    grid.className = "grid";
    for (const [id, state, text] of items) {
      const card = document.createElement("article");
      card.className = "card";
      const tag = document.createElement("span");
      tag.className = "tag " + state;
      tag.textContent = label[state] || state;
      const idEl = document.createElement("div");
      idEl.className = "id";
      idEl.textContent = id;
      const h3 = document.createElement("h3");
      h3.textContent = text;
      card.append(tag, idEl, h3);
      grid.appendChild(card);
    }
    root.append(h2, grid);
  }
})();
